from __future__ import annotations
import json,sys
from pathlib import Path
import pandas as pd
import streamlit as st
APP_DIR=Path(__file__).resolve().parent; ROOT=APP_DIR.parents[1]; PAPER=ROOT.parent/'reasearch_paper'; sys.path.insert(0,str(APP_DIR))
from nb_model import MixedNaiveBayes
from trace import render_trace
import viz
st.set_page_config(page_title="Cedar Bayes Lab",page_icon="◒",layout="wide")
st.markdown("<style>.block-container{max-width:1120px;padding-top:2rem}.stAlert{border-radius:14px}</style>",unsafe_allow_html=True)
SAFETY="Educational demo only — trained on a 1980s, single-site dataset of 303 records. It is not a medical device or diagnostic tool. Its probabilities were less well calibrated than logistic regression (Brier 0.183 vs 0.168)."
@st.cache_data
def load_data(): return pd.read_csv(PAPER/'heart_cleveland_clean.csv')
@st.cache_data
def load_results(): return json.loads((PAPER/'results.json').read_text())
@st.cache_resource
def load_model(): return MixedNaiveBayes().fit(load_data())
data,results,model=load_data(),load_results(),load_model()
st.sidebar.markdown("## ◒ Cedar Bayes Lab\nMixed Naive Bayes · UCI Cleveland")
page=st.sidebar.radio("Explore",["Predict","Data & Results","About"]); st.warning(SAFETY,icon="⚠️")
if page=="Predict":
    st.title("Explore model arithmetic"); st.caption("Inputs describe a hypothetical record. The result is a model output, never medical advice.")
    defaults={"age":55,"trestbps":130,"chol":245,"thalach":150,"cp":3,"exang":0}
    with st.form("predict"):
        a,b,c=st.columns(3); values={"age":a.slider("Age",20,100,55),"trestbps":b.slider("Resting BP (mm Hg)",80,220,130),"chol":c.slider("Cholesterol (mg/dl)",100,600,245),"thalach":a.slider("Maximum heart rate",60,220,150),"cp":b.selectbox("Chest pain type",[1,2,3,4],format_func=lambda x:{1:"1 — Typical angina",2:"2 — Atypical angina",3:"3 — Non-anginal pain",4:"4 — Asymptomatic"}[x],index=2),"exang":c.selectbox("Exercise-induced angina",[0,1],format_func=lambda x:"0 — Absent" if x==0 else "1 — Present")}; submitted=st.form_submit_button("Calculate model output",type="primary")
    if not submitted: values=defaults
    theta=st.slider("Decision threshold θ",.30,.70,.50,.05); p=model.predict_one(values); left,right=st.columns(2); left.metric("Model positive-class probability",f"{p.probability:.1%}"); right.metric("Thresholded model label","positive class" if p.probability>=theta else "control class")
    st.caption("The label is the model's thresholded class, not a diagnosis or a statement about a person."); st.plotly_chart(viz.contributions_bar(p.contributions),use_container_width=True)
    near=min(results["threshold_sweep"],key=lambda x:abs(float(x)-theta)); st.info(f"Paper sweep nearest θ={near}: recall {results['threshold_sweep'][near]['recall']:.1%}; specificity {results['threshold_sweep'][near]['specificity']:.1%}.")
    with st.expander("Stats for nerds — full calculation trace"): render_trace(model,values,theta,PAPER/'heart_cleveland_clean.csv',data.loc[data.target==0])
elif page=="Data & Results":
    st.title("Data & results"); st.plotly_chart(viz.class_balance(data),use_container_width=True); a,b=st.columns(2); a.plotly_chart(viz.categorical_distribution(data,"cp"),use_container_width=True); b.plotly_chart(viz.categorical_distribution(data,"exang"),use_container_width=True)
    st.plotly_chart(viz.gaussian_histograms(data),use_container_width=True); st.plotly_chart(viz.correlation_heatmaps(data),use_container_width=True); st.plotly_chart(viz.cv_metrics(results),use_container_width=True); st.plotly_chart(viz.threshold_sweep(results),use_container_width=True)
    st.subheader("Filterable source records"); classes=st.multiselect("Recorded target",sorted(data.target.unique()),default=sorted(data.target.unique())); st.dataframe(data[data.target.isin(classes)],use_container_width=True)
    st.caption("ROC and reliability curves are retained in the paper figures; results.json contains their summary metrics, not individual out-of-fold probabilities.")
else:
    st.title("About Cedar Bayes Lab"); st.markdown("A transparent educational interface for the paper's mixed Gaussian–categorical Naive Bayes model. Dataset: [UCI Heart Disease — Cleveland subset](https://doi.org/10.24432/C52P4X).")
    st.subheader("Limitations"); st.write("Historical, single-site data; small sample; Gaussian departures; and conditional dependence mean these outputs must not be used for clinical decisions.")
    st.subheader("AI-assistance disclosure"); st.write("Generative AI tools were used as learning and editorial assistants to explain statistical concepts, revise manuscript wording and organization, review consistency between the report and project code, and suggest citation checks. The reported numerical results were generated by the documented Python pipeline; AI suggestions were not treated as evidence or as a substitute for cited sources. The author is responsible for verifying the data, code, calculations, references, and interpretations, and for understanding and explaining the work.")
